import Model from 'flarum/common/Model';
/** A reviewed product (MyBB "product"), with its counts and averages kept on the row. */
export default class Item extends Model {
  name = Model.attribute('name');
  slug = Model.attribute('slug');
  brand = Model.attribute('brand');
  fields = Model.attribute('fields');
  status = Model.attribute('status');
  reviewCount = Model.attribute('reviewCount');
  commentCount = Model.attribute('commentCount');
  viewCount = Model.attribute('viewCount');
  rating = Model.attribute('rating');
  rank = Model.attribute('rank');
  criteriaAverages = Model.attribute('criteriaAverages');
  distribution = Model.attribute('distribution');
  topMentions = Model.attribute('topMentions');
  thumbnailUrl = Model.attribute('thumbnailUrl');
  photoUrl = Model.attribute('photoUrl');
  createdAt = Model.attribute('createdAt', Model.transformDate);
  lastActivityAt = Model.attribute('lastActivityAt', Model.transformDate);
  canEdit = Model.attribute('canEdit');
  canDelete = Model.attribute('canDelete');
  canModerate = Model.attribute('canModerate');
  canReview = Model.attribute('canReview');
  canComment = Model.attribute('canComment');
  canReport = Model.attribute('canReport');
  category = Model.hasOne('category');
  user = Model.hasOne('user');

  /** The URL slug: id plus name, like discussions. */
  urlId() {
    return `${this.id()}-${this.slug()}`;
  }
}
flarum.reg.add('ernestdefoe-community-reviews', 'forum/models/Item', Item);